const sessionKinds = new Set(["claude_code_session", "codex_session"]);

export function legacyEvidenceProvenance({ source_id, source_kind, source_locator, episode_id, speaker }) {
  const session = sessionKinds.has(source_kind) && !source_locator?.startsWith("tbrain:");
  // Only these suffixes were generated by the session ingestion paths.
  const key = session && source_locator
    ? source_locator.replace(/:(?:turns:[0-9]+|sync:[a-f0-9]{64})$/, "") : null;
  return {
    observation_group: key && source_id ? `${source_id}:${key}` : episode_id,
    role: session && speaker === "tony" ? "user" : session && speaker === "assistant" ? "assistant" : "unknown",
    fidelity: "unknown",
  };
}

export function legacyEvidenceRoleSql({ sourceKind, sourceLocator, speaker }) {
  return `case when ${sourceKind} in ('claude_code_session','codex_session')
    and (${sourceLocator} is null or ${sourceLocator} not like 'tbrain:%')
    then case ${speaker} when 'tony' then 'user' when 'assistant' then 'assistant' else 'unknown' end
    else 'unknown' end`;
}
